<?php
require __DIR__.'/../lib/bootstrap.php';require_admin();
try{
 if($_SERVER['REQUEST_METHOD']==='GET'){if(isset($_GET['id'])){$q=db()->prepare('SELECT * FROM products WHERE id=?');$q->execute([(int)$_GET['id']]);$p=$q->fetch();$i=db()->prepare('SELECT * FROM product_images WHERE product_id=? ORDER BY is_cover DESC,sort_order,id');$i->execute([(int)$_GET['id']]);json_response(['product'=>$p,'images'=>$i->fetchAll()]);}$q=db()->query('SELECT p.*,c.name category_name,(SELECT path FROM product_images i WHERE i.product_id=p.id ORDER BY i.is_cover DESC,i.sort_order LIMIT 1) image FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.updated_at DESC');json_response(['products'=>$q->fetchAll()]);}
 require_csrf();$d=input();$action=$d['action']??'save';
 if($action==='delete'){db()->prepare('DELETE FROM products WHERE id=?')->execute([(int)$d['id']]);json_response(['ok'=>true]);}
 if($action==='toggle'){$field=$d['field']??'';if(!in_array($field,['is_published','is_featured'],true))json_response(['error'=>'Acción no válida'],422);$id=(int)($d['id']??0);if(!$id)json_response(['error'=>'Producto no válido'],422);$value=!empty($d['value'])?1:0;$q=db()->prepare("UPDATE products SET $field=? WHERE id=?");$q->execute([$value,$id]);if(!$q->rowCount()){$exists=db()->prepare('SELECT id FROM products WHERE id=?');$exists->execute([$id]);if(!$exists->fetch())json_response(['error'=>'El producto ya no existe'],404);}$q=db()->prepare('SELECT is_published,is_featured FROM products WHERE id=?');$q->execute([$id]);json_response(['ok'=>true,'product'=>$q->fetch()]);}
 $id=(int)($d['id']??0);$quick=($d['mode']??'')==='quick';$name=trim($d['name']??'');if($name==='')json_response(['error'=>'El nombre es obligatorio'],422);if(!$quick&&!empty($d['is_offer'])){$price=$d['price']===''?null:(float)$d['price'];$oldPrice=$d['old_price']===''?null:(float)$d['old_price'];if($price===null||$oldPrice===null)json_response(['error'=>'Una oferta requiere precio normal y precio oferta.'],422);if($oldPrice<=$price)json_response(['error'=>'El precio normal debe ser mayor que el precio oferta.'],422);}
 if($quick){$q=db()->prepare('UPDATE products SET name=?,category_id=?,short_description=?,long_description=?,price=?,stock=?,is_published=? WHERE id=?');$q->execute([$name,$d['category_id']?:null,$d['short_description']?:null,$d['long_description']?:null,$d['price']===''?null:$d['price'],$d['stock']===''?null:$d['stock'],!empty($d['is_published']),$id]);json_response(['ok'=>true,'id'=>$id]);}
 $fields=['category_id','name','slug','sku','brand','short_description','long_description','seo_title','seo_description','is_indexable','price','old_price','stock','stock_mode','is_featured','is_offer','is_published','sort_order'];
 $vals=[];foreach($fields as $f){$v=$d[$f]??null;if(in_array($f,['category_id','price','old_price','stock','sku','brand','short_description','long_description','seo_title','seo_description'],true)&&$v==='')$v=null;if(in_array($f,['is_indexable','is_featured','is_offer','is_published'],true))$v=!empty($v)?1:0;if($f==='slug')$v=trim((string)$v)?:slugify($name);$vals[]=$v;}
 if($id){$sets=implode(',',array_map(fn($f)=>"$f=?",$fields));$vals[]=$id;db()->prepare("UPDATE products SET $sets WHERE id=?")->execute($vals);}else{$marks=implode(',',array_fill(0,count($fields),'?'));db()->prepare('INSERT INTO products('.implode(',',$fields).") VALUES($marks)")->execute($vals);$id=(int)db()->lastInsertId();}
 json_response(['ok'=>true,'id'=>$id]);
}catch(PDOException $e){json_response(['error'=>$e->getCode()==='23000'?'El slug o SKU ya está en uso.':'No fue posible guardar el producto.'],422);}catch(Throwable $e){json_response(['error'=>$e->getMessage()],500);}
